package app.dayflow;
import org.json.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
import android.widget.*;
import com.google.android.material.textfield.TextInputEditText;

/** Synced three-level type tree. Basic behavior is inherited from its root. */
public final class TaskTypes {
    public static void seed(MainActivity a)throws JSONException{
        String[] names={"普通任务","长任务","待办"},kinds={"event","project","task"};
        for(int i=0;i<names.length;i++){String id=UUID.nameUUIDFromBytes(("dayflow:type:"+kinds[i]).getBytes(StandardCharsets.UTF_8)).toString();if(Data.get(a).find(id)==null){JSONObject r=Data.make("type",names[i]).put("id",id).put("system_type",true).put("base_kind",kinds[i]);r.put("revision",UUID.nameUUIDFromBytes(("dayflow:type:initial:"+kinds[i]).getBytes(StandardCharsets.UTF_8)).toString());Data.get(a).save(r);}}
    }
    public static List<JSONObject> all(MainActivity a,boolean archived)throws JSONException{seed(a);JSONArray rows=Data.get(a).list("type",500);List<JSONObject> result=new ArrayList<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(archived||!r.optBoolean("archived"))result.add(r);}return result;}
    public static int depth(JSONObject type,List<JSONObject> rows){Set<String> seen=new HashSet<>();int depth=1;while(!type.optString("parent_id").isEmpty()){if(!seen.add(type.optString("id")))return 99;String id=type.optString("parent_id");JSONObject parent=null;for(JSONObject r:rows)if(id.equals(r.optString("id"))){parent=r;break;}if(parent==null)return 99;type=parent;depth++;}return depth;}
    public static String path(JSONObject type,List<JSONObject> rows){String name=type.optString("title");Set<String> seen=new HashSet<>();while(!type.optString("parent_id").isEmpty()&&seen.add(type.optString("id"))){String id=type.optString("parent_id");JSONObject parent=null;for(JSONObject r:rows)if(id.equals(r.optString("id"))){parent=r;break;}if(parent==null)break;name=parent.optString("title")+" / "+name;type=parent;}return name;}
    public static String label(MainActivity a,String id){try{JSONObject t=Data.get(a).find(id);return t==null?"":t.optString("icon")+" "+t.optString("title");}catch(Exception e){return "";}}
    public static android.widget.TextView badge(MainActivity a,String id){try{JSONObject type=Data.get(a).find(id);if(type==null)return null;android.widget.TextView label=Ui.help(a,type.optString("icon")+" "+type.optString("title"));String tint=type.optString("color");if(tint.matches("#[0-9a-fA-F]{6}")){android.graphics.drawable.GradientDrawable dot=new android.graphics.drawable.GradientDrawable();dot.setShape(android.graphics.drawable.GradientDrawable.OVAL);dot.setColor(android.graphics.Color.parseColor(tint));dot.setStroke(Ui.dp(a,1),Ui.color(a,com.google.android.material.R.attr.colorOutlineVariant));dot.setBounds(0,0,Ui.dp(a,10),Ui.dp(a,10));label.setCompoundDrawables(dot,null,null,null);label.setCompoundDrawablePadding(Ui.dp(a,6));}return label;}catch(Exception e){return null;}}
    public static void show(MainActivity a){try{List<JSONObject> rows=all(a,true);LinearLayout page=a.fullPage("任务类型",a::home);page.addView(Ui.text(a,"任务类型",24,true));page.addView(Ui.help(a,"最多三级。子类型继承根类型的普通任务、长任务或待办行为；类型及归档状态随数据同步。"));page.addView(Ui.button(a,"＋ 新建类型",true,()->edit(a,null)));
        rows.sort(Comparator.comparing(r->path(r,rows)));for(JSONObject r:rows)page.addView(Ui.button(a,(r.optBoolean("archived")?"已归档 · ":"")+r.optString("icon")+" "+path(r,rows),false,()->edit(a,r)));
    }catch(Exception e){a.message(e.getMessage());}}
    private static void edit(MainActivity a,JSONObject original){try{List<JSONObject> rows=all(a,true);JSONObject r=original==null?Data.make("type",""):new JSONObject(original.toString());LinearLayout page=a.fullPage("编辑类型",()->show(a));TextInputEditText name=Ui.field(a,page,"类型名称",r.optString("title"),false),icon=Ui.field(a,page,"图标（选填）",r.optString("icon"),false),color=Ui.field(a,page,"颜色（#RRGGBB，选填）",r.optString("color"),false);
        List<JSONObject> parents=new ArrayList<>();List<String> labels=new ArrayList<>();labels.add("无父类型");for(JSONObject row:rows)if(!row.optBoolean("archived")&&!row.optString("id").equals(r.optString("id"))&&depth(row,rows)<3){parents.add(row);labels.add(path(row,rows));}
        Spinner parent=spinner(a,page,"父类型",labels);for(int i=0;i<parents.size();i++)if(parents.get(i).optString("id").equals(r.optString("parent_id")))parent.setSelection(i+1);
        Spinner behavior=spinner(a,page,"根类型行为",Arrays.asList("普通任务","长任务","待办"));String[] kinds={"event","project","task"};for(int i=0;i<3;i++)if(kinds[i].equals(r.optString("base_kind")))behavior.setSelection(i);if(original!=null){parent.setEnabled(false);behavior.setEnabled(false);}
        page.addView(Ui.button(a,"保存类型",true,()->{try{String title=name.getText().toString().trim();if(title.isEmpty())throw new Exception("请填写名称");String tint=color.getText().toString().trim();if(!tint.isEmpty()&&!tint.matches("#[0-9a-fA-F]{6}"))throw new Exception("颜色格式应为 #RRGGBB");JSONObject root=parent.getSelectedItemPosition()==0?null:parents.get(parent.getSelectedItemPosition()-1);r.put("title",title).put("icon",icon.getText().toString()).put("color",tint).put("parent_id",root==null?"":root.optString("id")).put("base_kind",root==null?kinds[behavior.getSelectedItemPosition()]:root.optString("base_kind"));Data.validate(r);Data.get(a).save(r);a.changed();show(a);}catch(Exception e){a.message(e.getMessage());}}));
        if(original!=null&&!r.optBoolean("system_type")){page.addView(Ui.button(a,r.optBoolean("archived")?"恢复类型":"归档类型",false,()->{try{if(!r.optBoolean("archived"))for(JSONObject child:rows)if(r.optString("id").equals(child.optString("parent_id"))&&!child.optBoolean("archived"))throw new Exception("请先归档或合并子类型");r.put("archived",!r.optBoolean("archived"));Data.get(a).save(r);a.changed();show(a);}catch(Exception e){a.message(e.getMessage());}}));page.addView(Ui.button(a,"合并到其他类型…",false,()->mergePage(a,r)));}
    }catch(Exception e){a.message(e.getMessage());}}
    private static void mergePage(MainActivity a,JSONObject source){try{LinearLayout page=a.fullPage("合并类型",()->edit(a,source));page.addView(Ui.help(a,"选择同一基础行为的目标类型。已有事项将迁移，原类型归档；有子类型时请先处理子类型。"));for(JSONObject target:all(a,false))if(!target.optString("id").equals(source.optString("id"))&&target.optString("base_kind").equals(source.optString("base_kind")))page.addView(Ui.button(a,target.optString("title"),false,()->a.job(()->{Data db=Data.get(a);JSONArray related=db.related("parent_id",source.getString("id"));for(int i=0;i<related.length();i++)if("type".equals(related.getJSONObject(i).optString("kind")))throw new Exception("请先处理子类型");int count=db.mergeType(source,target);return "类型已合并，迁移 "+count+" 条事项";},()->show(a))));}catch(Exception e){a.message(e.getMessage());}}
    public static Spinner spinner(MainActivity a,LinearLayout page,String label,List<String> names){page.addView(Ui.text(a,label,14,true));Spinner spinner=new Spinner(a);spinner.setMinimumHeight(Ui.dp(a,48));spinner.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,names));page.addView(spinner);return spinner;}
}
